#include <iostream>
using namespace std;

int main() {
    int N;
    cin >> N;                       // N >= 3
    int ANT = 0, ACT = 1, SEG;
    int TERME = 2;                  // términos ya escritos
    cout << ANT << " " << ACT << " ";
    do {
        SEG = ANT + ACT;            // 1. calcular el siguiente
        cout << SEG << " ";
        ANT = ACT;                  // 2. desplazar: primero ANT...
        ACT = SEG;                  //    ...después ACT
        TERME++;
    } while (TERME < N);
    cout << endl;
    return 0;
}

