#include <iostream>
using namespace std;

int main() {
    int x;
    cin >> x;                    // por ejemplo 1011
    int R = 0, pot = 1;
    while (x > 0) {
        int xifra = x % 10;      // 1, 1, 0, 1
        R = R + xifra * pot;     // + 1, + 2, + 0, + 8
        pot = pot * 2;           // 1, 2, 4, 8, ...
        x = x / 10;
    }
    cout << "Decimal: " << R << endl;
    return 0;
}

