        double nota;
        cin >> nota;
        if (nota < 5) {
            totesAprovades = false;    // basta con una para desmentirlo
        }
        if (nota >= 9) {
            algunaExcellent = true;    // basta con una para confirmarlo
        }
    }
    if (totesAprovades) cout << "Totes aprovades: si" << endl;
    else cout << "Totes aprovades: no" << endl;
    if (algunaExcellent) cout << "Alguna excel.lent: si" << endl;
    else cout << "Alguna excel.lent: no" << endl;
    return 0;
}

