#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;                       // n > 1
    int d = 2;
    bool trobat = false;
    while (d < n && !trobat) {
        if (n % d == 0) {
            trobat = true;          // NO se incrementa: d es el divisor
        } else {
            d++;
        }
    }
    if (trobat) {
        cout << n << " no es primer (divisible per " << d << ")" << endl;
    } else {
        cout << n << " es primer" << endl;
    }
    return 0;
}

